update public.learning_paths
set
  title = 'Learning and Behavior',
  goal = 'Learning and Behavior',
  summary = 'Define learning as behavior change through experience, connect major traditions, and establish the course''s experimental and applied logic. Topics explain classical and operant conditioning, reinforcement, punishment, avoidance, schedules, choice, extinction, relapse, and stimulus control; observational learning; cognitive, neural, and evolutionary perspectives; motivation, emotion, stress, skill learning, habits, and self-regulation; behavior modification and applied behavior analysis; learning in education, health, organizations, and technology; and contemporary debates, computational models, and a capstone behavior-change project.',
  data = $lbehjson${"slug": "learning-and-behavior", "title": "Learning and Behavior", "description": "Define learning as behavior change through experience, connect major traditions, and establish the course's experimental and applied logic. Topics explain classical and operant conditioning, reinforcement, punishment, avoidance, schedules, choice, extinction, relapse, and stimulus control; observational learning; cognitive, neural, and evolutionary perspectives; motivation, emotion, stress, skill learning, habits, and self-regulation; behavior modification and applied behavior analysis; learning in education, health, organizations, and technology; and contemporary debates, computational models, and a capstone behavior-change project.", "topics": [{"id": "1e4329c0-8353-4eb2-8be2-1d6f64c74d07", "type": "topic", "title": "Foundations of Learning Science and Behavior Analysis", "description": "Define learning as behavior change through experience, connect major traditions, and establish the course's experimental and applied logic.", "children": [{"id": "62d88ff9-9aa5-4aae-82e2-e464af6081f9", "type": "subtopic", "title": "What Counts as Learning", "children": [{"id": "85e9b9f4-df4c-4238-83f4-dcc9c22f8e71", "type": "concept", "title": "Behavior vs behavioral potential"}, {"id": "d7eef5ac-4b22-4df9-9349-4fae52e26e8c", "type": "concept", "title": "Experience and practice"}, {"id": "414f5954-7a5d-48ee-bab6-73b4c9fb3a30", "type": "concept", "title": "Performance vs learning"}, {"id": "83f86996-5e2d-4947-afd6-0a1484851e63", "type": "concept", "title": "Maturation, fatigue, and drug effects"}], "description": "This subtopic establishes learning as a measurable change in behavior or behavioral potential caused by experience, not simply maturation or temporary state change."}, {"id": "753a4b9b-93ba-4b6c-8405-8edb92d2e4fd", "type": "subtopic", "title": "History of Learning Theory", "children": [{"id": "44f6c607-d539-4414-9454-c3622a044536", "type": "concept", "title": "Associationism"}, {"id": "232c15b0-3c06-4c3f-8b2b-b36fd921a089", "type": "concept", "title": "Pavlov and Thorndike"}, {"id": "8e9e26b6-cab1-4c94-9bc8-b0a342141f0c", "type": "concept", "title": "Watson and Skinner"}, {"id": "39e46ba9-5777-4643-a027-bf4d208cb412", "type": "concept", "title": "Tolman, Bandura, and cognitive turns"}], "description": "A strong foundation requires seeing how associationism, behaviorism, cognitive psychology, and behavior analysis each framed the study of change."}, {"id": "d5d10e46-0b75-41c9-89dd-e164c379915e", "type": "subtopic", "title": "Scientific Method in Learning Research", "children": [{"id": "ae53a89b-6db6-4b90-a39c-c606b73823eb", "type": "concept", "title": "Independent and dependent variables"}, {"id": "9c73b8b4-57db-4615-8404-711c08b9842d", "type": "concept", "title": "Within-subject designs"}, {"id": "e6900b77-5916-4e68-91b4-86277b46b550", "type": "concept", "title": "Single-case logic"}, {"id": "05d7b54f-3952-411b-a484-72c23263769a", "type": "concept", "title": "Reliability, validity, and replication"}], "description": "Learning and behavior are studied through careful operational definitions, experimental control, replication, and precise measurement."}]}, {"id": "bdada2f9-e0b7-4e0b-bd40-8a3411330973", "type": "topic", "title": "Classical Conditioning and Associative Learning", "description": "Explain how organisms learn predictive relations among stimuli and why these associations matter for emotion, preparation, and adaptation.", "children": [{"id": "9c9d9770-3aae-44ed-9628-9c96af6a26b4", "type": "subtopic", "title": "Basic Classical Conditioning", "children": [{"id": "5c607b18-eef2-45a8-9368-7e54cd36c653", "type": "concept", "title": "Unconditioned stimulus and response"}, {"id": "a435aeed-79a8-4a05-8b7a-3a445bca51ab", "type": "concept", "title": "Conditioned stimulus and response"}, {"id": "5f9476e3-8246-4c82-8be5-122b4e80db70", "type": "concept", "title": "Acquisition"}, {"id": "a83d6bf1-0ec3-415f-bb20-6f04ccda2d3d", "type": "concept", "title": "Timing and contiguity"}], "description": "Classical conditioning explains how neutral cues become meaningful predictors of biologically important events."}, {"id": "0b39ffce-b41d-4b34-834e-b9eb979525e0", "type": "subtopic", "title": "Associative Mechanisms", "children": [{"id": "c65b82a9-4d8a-45b2-b222-cf7eba7ed9c7", "type": "concept", "title": "Contingency vs contiguity"}, {"id": "434cc379-1b83-498c-afd5-19cea669901b", "type": "concept", "title": "Blocking"}, {"id": "b8c091ff-e7e6-4169-aebc-f4dfb8712581", "type": "concept", "title": "Prediction error"}, {"id": "692624f6-aafc-43a4-9b12-6dd80e8ed08e", "type": "concept", "title": "Rescorla-Wagner model"}], "description": "Modern accounts ask what exactly is learned: a simple link, a prediction, an expectation, or a representation of event relations."}, {"id": "24c34d6e-a9a5-45c0-a3f7-25611570b4bf", "type": "subtopic", "title": "Emotional and Physiological Conditioning", "children": [{"id": "6007426e-87d7-478a-9bf7-7f905c41dd37", "type": "concept", "title": "Fear conditioning"}, {"id": "328184e8-1499-4adb-bf9e-e7889631627c", "type": "concept", "title": "Conditioned emotional response"}, {"id": "093292cf-9641-497d-8b68-157509c25157", "type": "concept", "title": "Taste aversion"}, {"id": "8e1bee6a-fb88-41a4-b46c-971b03f56816", "type": "concept", "title": "Conditioned tolerance and cue reactivity"}], "description": "Conditioning is central to fear, taste aversion, immune responses, addiction cues, and preparedness for action."}]}, {"id": "b41efea8-2411-4027-a9c9-8253c44f6d70", "type": "topic", "title": "Operant Conditioning and Consequences", "description": "Analyze how consequences shape voluntary behavior through reinforcement, punishment, response cost, shaping, and feedback.", "children": [{"id": "e93b0755-46d7-4293-a8f7-80f4d6d601d2", "type": "subtopic", "title": "Thorndike, Skinner, and Operant Logic", "children": [{"id": "c423192c-fad3-4287-ab05-79e392cdf6db", "type": "concept", "title": "Law of effect"}, {"id": "033e4c58-5676-46d0-958e-1656860a6d72", "type": "concept", "title": "Operant chamber"}, {"id": "32c54a97-6e6f-443f-a5a8-b693db886570", "type": "concept", "title": "Response classes"}, {"id": "5fcbadb6-707d-463a-a6e5-9da130f2ad1b", "type": "concept", "title": "Three-term contingency"}], "description": "Operant conditioning studies how behavior is selected by its consequences in a particular environment."}, {"id": "6d240431-bfd6-487b-b323-73d95626196d", "type": "subtopic", "title": "Reinforcement and Response Strength", "children": [{"id": "f1dcffc8-a1a5-4ab6-bd8c-8e90a40ac408", "type": "concept", "title": "Positive reinforcement"}, {"id": "971fdc45-1261-44b3-838b-e1268f26e26c", "type": "concept", "title": "Negative reinforcement"}, {"id": "49e4a316-71c2-43f7-8d06-eaff55e3d746", "type": "concept", "title": "Primary and conditioned reinforcers"}, {"id": "45eb401c-2f76-49cd-9e81-76cdad363826", "type": "concept", "title": "Immediacy and magnitude"}], "description": "Reinforcement is the process by which consequences increase future behavior, but its effects depend on timing, value, and context."}, {"id": "9055872d-18c8-4c9b-9c9c-92459775de62", "type": "subtopic", "title": "Shaping and Chaining", "children": [{"id": "23803dbc-4ac3-4def-b049-f1ea849a7743", "type": "concept", "title": "Successive approximations"}, {"id": "356d0010-4157-4178-a0cc-abb9e53cd8f4", "type": "concept", "title": "Prompting and fading"}, {"id": "2ad3f3ae-0788-4390-9768-e6f77d8bd999", "type": "concept", "title": "Task analysis"}, {"id": "0121418d-5ee0-44ce-9724-b08566761f24", "type": "concept", "title": "Forward and backward chaining"}], "description": "Complex behavior is often built gradually by reinforcing approximations and linking smaller responses into useful sequences."}]}, {"id": "8896a53f-d8b0-40a3-b30a-8d38383d4733", "type": "topic", "title": "Reinforcement, Punishment, Avoidance, and Behavioral Momentum", "description": "Compare consequence-based processes and learn how they strengthen, suppress, redirect, or maintain behavior over time.", "children": [{"id": "6cc141d0-c48f-4838-8ba9-04a450aaf0b7", "type": "subtopic", "title": "Punishment and Response Suppression", "children": [{"id": "a8caea26-8cc1-4284-98f1-ef3a7585e71d", "type": "concept", "title": "Positive punishment"}, {"id": "38a11b5c-1e40-4ff5-9a27-f7e45a75fcf2", "type": "concept", "title": "Negative punishment"}, {"id": "db46898e-adde-41d7-9c44-ec7c48b6cd12", "type": "concept", "title": "Response cost"}, {"id": "7e0f876e-3a5c-4df8-be2a-ddda686a9c51", "type": "concept", "title": "Side effects and ethical limits"}], "description": "Punishment can reduce behavior, but it raises practical, ethical, and side-effect questions that must be handled carefully."}, {"id": "1aec6616-23c0-48eb-8fe7-d4f8ba5c80ca", "type": "subtopic", "title": "Avoidance and Escape Learning", "children": [{"id": "9be2355b-55cc-4833-bed2-95b8e7c51606", "type": "concept", "title": "Escape conditioning"}, {"id": "967617bd-acd4-4a8a-b9e1-3b86ea1ee9d4", "type": "concept", "title": "Avoidance schedules"}, {"id": "41409dfb-db86-4c62-b7c9-496d742503f1", "type": "concept", "title": "Two-factor theory"}, {"id": "93f0965c-a499-465d-9ba7-cd7895780a4f", "type": "concept", "title": "Learned helplessness and controllability"}], "description": "Avoidance learning shows how behavior can be maintained by preventing or ending aversive events, even when danger is absent."}, {"id": "cf2aaa30-1f30-4937-af26-8aa3ecd9ff54", "type": "subtopic", "title": "Behavioral Momentum", "children": [{"id": "d3494ce4-675a-4819-9dda-4408bf573652", "type": "concept", "title": "Baseline reinforcement rate"}, {"id": "300eb6ec-391d-464a-a393-83a877df56fa", "type": "concept", "title": "Persistence"}, {"id": "a7e515cd-3c5b-49dd-943f-d69bc53c4e4b", "type": "concept", "title": "Disruptors"}, {"id": "947a9ecc-892f-4169-8462-47f7d9b6eb88", "type": "concept", "title": "High-probability request sequences"}], "description": "Behavioral momentum explains why some behavior persists despite disruption and how reinforcement history affects resistance to change."}]}, {"id": "fc50b496-97ee-4e6c-9b7a-bce0ec83665a", "type": "topic", "title": "Schedules of Reinforcement, Choice, and Matching", "description": "Study how timing and probability of consequences create distinctive patterns of behavior and decision making.", "children": [{"id": "ec0debe8-a23e-4d61-9e33-815f78225184", "type": "subtopic", "title": "Ratio and Interval Schedules", "children": [{"id": "1a8dae19-b637-4332-aa17-5358305320e0", "type": "concept", "title": "Fixed ratio"}, {"id": "9ef0c859-6716-4aa9-a164-ac774e929324", "type": "concept", "title": "Variable ratio"}, {"id": "aad57ffe-f9ba-4559-8a00-d9422c884959", "type": "concept", "title": "Fixed interval"}, {"id": "393cca4b-cff0-4ac8-9b40-f6b0bfc1ab67", "type": "concept", "title": "Variable interval"}], "description": "Schedules of reinforcement reveal how the pattern of consequences controls response rate, pauses, and persistence."}, {"id": "000cfb0a-8cdf-4dfd-afc7-3aa9bea716eb", "type": "subtopic", "title": "Differential Reinforcement", "children": [{"id": "0cbcd00f-89f4-4817-8346-2d2f1d0ba7fc", "type": "concept", "title": "DRA"}, {"id": "7e50c8f1-b0f2-47e3-9991-9a11c6e8b23f", "type": "concept", "title": "DRI"}, {"id": "15400e93-60f6-4ddc-b655-ec2733da6b6b", "type": "concept", "title": "DRO"}, {"id": "f3c7de2d-5934-4a60-8a9e-6f55169b5d21", "type": "concept", "title": "DRL and DRH"}], "description": "Differential reinforcement teaches learners which forms, rates, or timing of behavior are useful."}, {"id": "305a06ea-2e03-4b48-b690-49777537e488", "type": "subtopic", "title": "Choice and Matching", "children": [{"id": "42d8606e-5fed-4170-bb41-921e344e7385", "type": "concept", "title": "Matching law"}, {"id": "8e11c277-d3b1-4a46-b0b9-3dd2e996d597", "type": "concept", "title": "Concurrent schedules"}, {"id": "6a4a35ec-e8b1-4809-95ca-a6b82f303cb1", "type": "concept", "title": "Delay discounting"}, {"id": "224b6c3a-4840-457a-8da7-78869276ca24", "type": "concept", "title": "Melioration and self-control"}], "description": "Choice research links learning to allocation of behavior across options, rewards, delays, and effort."}]}, {"id": "d74da1a5-6046-4fda-bd62-8c9601a9133f", "type": "topic", "title": "Extinction, Spontaneous Recovery, Renewal, and Relapse", "description": "Understand why learned behavior returns after change efforts and how durable behavior change is designed.", "children": [{"id": "ee9a01e9-9eaf-423a-af96-cc593847ad42", "type": "subtopic", "title": "Extinction Processes", "children": [{"id": "051562a9-013d-469d-a199-21e366f5cad7", "type": "concept", "title": "Extinction bursts"}, {"id": "befc3c3c-70c0-4e00-aaa3-fa72e4ef18fd", "type": "concept", "title": "Emotional responding"}, {"id": "ca823239-4948-4749-afb4-86edcc7831ff", "type": "concept", "title": "Extinction as inhibitory learning"}, {"id": "64bc8397-f1be-4bdc-8a11-f59932f3cce4", "type": "concept", "title": "Context dependence"}], "description": "Extinction is not erasure; it is new learning that behavior or cues no longer produce the expected outcome."}, {"id": "80fde040-da2a-4e08-9f6b-bef03d42056a", "type": "subtopic", "title": "Recovery and Return of Behavior", "children": [{"id": "972569e9-2bce-442d-a73d-d8188d4da974", "type": "concept", "title": "Spontaneous recovery"}, {"id": "72239095-a812-4990-be83-f272b9c8e4f2", "type": "concept", "title": "Renewal"}, {"id": "b6177246-2c1f-47ad-aa13-3080df6cb4e4", "type": "concept", "title": "Reinstatement"}, {"id": "1466d999-df96-495d-80f9-7fe1025fff26", "type": "concept", "title": "Resurgence"}], "description": "Behavior often comes back, so students need to understand the major relapse phenomena before designing interventions."}, {"id": "42c41960-432f-4ebc-babb-8436808201d8", "type": "subtopic", "title": "Durable Behavior Change", "children": [{"id": "de43f751-353f-4a1e-907f-02612067ee88", "type": "concept", "title": "Thinning reinforcement"}, {"id": "5dc642db-8d12-4f5d-8d52-8af74ea94f4b", "type": "concept", "title": "Multiple contexts"}, {"id": "f532254a-7741-4ce3-ad8f-28a54cb36a56", "type": "concept", "title": "Booster sessions"}, {"id": "ae973330-fdac-4564-8b63-37e41e901d92", "type": "concept", "title": "Replacement behavior maintenance"}], "description": "Durable change requires planning for generalization, maintenance, competing reinforcement, and real-world relapse risks."}]}, {"id": "52e7e5d6-0fe5-4ed6-ba92-b908ab1e9c69", "type": "topic", "title": "Stimulus Control, Discrimination, Generalization, and Context", "description": "Learn how cues, settings, categories, and contexts guide behavior and transfer learning across situations.", "children": [{"id": "39b156b4-3fff-4219-a875-279cee80b2eb", "type": "subtopic", "title": "Stimulus Control", "children": [{"id": "21bbd5dc-4ba1-4fc6-a7d5-29321d7f881b", "type": "concept", "title": "Discriminative stimulus"}, {"id": "22db3ef8-6163-4842-9026-537a0e1c1ed4", "type": "concept", "title": "S-delta"}, {"id": "02ab7eb5-5080-4b48-8334-a0d3fe9affd1", "type": "concept", "title": "Cue salience"}, {"id": "4bfed1f9-f072-4389-942e-968c862b449e", "type": "concept", "title": "Occasion setting"}], "description": "Stimulus control explains how cues signal when behavior is likely to work, making behavior flexible and situation-sensitive."}, {"id": "e0c65cf1-eca7-442b-bc23-51dff651a71c", "type": "subtopic", "title": "Discrimination and Generalization", "children": [{"id": "94fe5459-4fdc-4df4-a9be-feddcec31b96", "type": "concept", "title": "Generalization gradients"}, {"id": "0fb363a7-b6b6-45c4-ab49-4e80bcbc228a", "type": "concept", "title": "Discrimination training"}, {"id": "a620c150-877c-4049-ae70-20779e0b0963", "type": "concept", "title": "Peak shift"}, {"id": "fd58fc7a-02d3-4ab2-a16b-ec729586768a", "type": "concept", "title": "Concept learning"}], "description": "Learners must know when to treat situations as different and when to transfer learning across similar cases."}, {"id": "bee8eb40-3530-451a-a966-c3bd7d0ef64d", "type": "subtopic", "title": "Context and Transfer", "children": [{"id": "48b2c8f1-76cd-4383-9ea2-12b1a6e2b6c4", "type": "concept", "title": "Physical context"}, {"id": "8faeccff-93b7-476a-880c-1cff5c3eccb6", "type": "concept", "title": "Social context"}, {"id": "656391e0-bcbd-41ad-b181-e5171e9cec50", "type": "concept", "title": "Internal state"}, {"id": "7338d25b-e03a-48d1-bdd7-2ea007fe7006", "type": "concept", "title": "Transfer-appropriate learning"}], "description": "Context determines whether learning appears, transfers, or disappears, especially in classrooms, clinics, workplaces, and natural environments."}]}, {"id": "a9f98253-77b9-4578-8899-8db750be849c", "type": "topic", "title": "Observational Learning, Imitation, and Social Learning", "description": "Examine how people and animals learn from models, social consequences, instruction, and culture.", "children": [{"id": "aa3e279c-3e67-4dcb-a9f5-e11206e45ad1", "type": "subtopic", "title": "Bandura and Social Learning", "children": [{"id": "24be3dc7-74e4-4115-bd00-9f3814bd6659", "type": "concept", "title": "Bobo doll studies"}, {"id": "8c631e70-dd6b-4a4b-ae95-00591c0ce77d", "type": "concept", "title": "Vicarious reinforcement"}, {"id": "be18495c-98d2-4cb7-bb3b-ff52c1a226ad", "type": "concept", "title": "Attention and retention"}, {"id": "37c825b6-c1fe-49ee-aae5-370be5011b92", "type": "concept", "title": "Motivation and reproduction"}], "description": "People learn by watching others, interpreting outcomes, and forming expectations, not only by direct reinforcement."}, {"id": "ae84bab3-9b7e-4de6-b574-4826b7582429", "type": "subtopic", "title": "Imitation and Modeling", "children": [{"id": "356a6d6f-d6ce-4751-88f8-38a85054138e", "type": "concept", "title": "Model characteristics"}, {"id": "7bee250e-56c0-41bd-b7e4-95105832d0f3", "type": "concept", "title": "Exact imitation"}, {"id": "ebc42a0a-1988-4069-bd9f-6c9ed876ed26", "type": "concept", "title": "Emulation"}, {"id": "34fc6d24-8478-440b-9db3-7689153ccc76", "type": "concept", "title": "Overimitation"}], "description": "Imitation is a powerful route to skill acquisition, social behavior, language, and cultural transmission."}, {"id": "e588be66-30df-4a61-869a-1960765ed9b0", "type": "subtopic", "title": "Social Influence and Culture", "children": [{"id": "621750f8-5182-4d21-8960-877fda31c968", "type": "concept", "title": "Norm learning"}, {"id": "1e19cc76-94f8-406f-bc70-a2b58124f301", "type": "concept", "title": "Peer effects"}, {"id": "35f63f1f-78bb-40e0-bac7-b4fc5bd026e2", "type": "concept", "title": "Instruction and rules"}, {"id": "56a5bf6a-8d12-44eb-9ce5-c543521d405f", "type": "concept", "title": "Cultural learning"}], "description": "Learning is embedded in norms, identities, institutions, and cultural practices that shape what is reinforced or punished."}]}, {"id": "ae650428-1837-4e55-b0c7-564f4a0c0eda", "type": "topic", "title": "Cognitive, Neural, and Evolutionary Perspectives on Learning", "description": "Integrate behaviorist findings with cognition, neuroscience, memory systems, animal cognition, and biological constraints.", "children": [{"id": "f335bc1c-1228-4144-bd17-09fbbbce46ca", "type": "subtopic", "title": "Cognitive Approaches", "children": [{"id": "58424bbd-78cb-4fd8-9f40-bd25688ba27b", "type": "concept", "title": "Latent learning"}, {"id": "eeeca182-b5b3-489a-bc2c-40c8e4c5733c", "type": "concept", "title": "Cognitive maps"}, {"id": "eb7dfac2-86d4-427f-bd8f-ee22233ebb29", "type": "concept", "title": "Expectancy theory"}, {"id": "8fea97a8-1da2-496e-ac2f-e8ea1af9cc68", "type": "concept", "title": "Attention and associability"}], "description": "Cognitive perspectives ask how expectations, attention, memory, maps, and beliefs shape learning."}, {"id": "6de37ed0-98db-46d7-bad3-fbaaa0108cae", "type": "subtopic", "title": "Neural Systems of Learning", "children": [{"id": "d350d1b3-de9f-4c0e-a593-70ce6b29dc46", "type": "concept", "title": "Dopamine prediction error"}, {"id": "5bb9a750-a4c0-461b-aed8-48dfec024763", "type": "concept", "title": "Hebbian learning"}, {"id": "14d87dad-f043-4dc0-8dce-667bd9122f7b", "type": "concept", "title": "Amygdala and fear"}, {"id": "5ff74347-be3c-4259-bb99-61300aa8714b", "type": "concept", "title": "Basal ganglia and habit learning"}], "description": "Learning changes the nervous system through plasticity, reward prediction, and interaction among memory systems."}, {"id": "ae35eb39-0334-4e99-a679-3fb328f559f6", "type": "subtopic", "title": "Biological Constraints and Animal Cognition", "children": [{"id": "80649912-f1e7-4bfe-aa7b-39f5a993c674", "type": "concept", "title": "Preparedness"}, {"id": "bbf05fe9-18e6-40e0-9b5f-c4e7b0500ae2", "type": "concept", "title": "Instinctive drift"}, {"id": "8b0b8039-f9f5-4e06-b79c-a95d782a7aeb", "type": "concept", "title": "Comparative cognition"}, {"id": "d454f4b0-4373-4143-9fd8-40d2774f29e0", "type": "concept", "title": "Foraging, navigation, and social learning"}], "description": "Organisms do not learn everything equally easily; evolution shapes preparedness, species differences, and adaptive specializations."}]}, {"id": "ada706eb-4bc9-40b6-8d86-5ccb001d07c1", "type": "topic", "title": "Motivation, Emotion, Stress, and Learning", "description": "Study how drives, incentives, arousal, affect, and stress alter what is learned and expressed.", "children": [{"id": "64cb1c8c-f059-40b8-a2b5-016a8b6caf2f", "type": "subtopic", "title": "Incentives and Motivation", "children": [{"id": "a61f6dd7-ebbc-4588-b981-1224303a9e92", "type": "concept", "title": "Drive reduction"}, {"id": "e37d7798-2b5e-4eab-9274-b95652c0174a", "type": "concept", "title": "Incentive value"}, {"id": "a578d3e4-d627-4d88-a7a3-0258c75007cb", "type": "concept", "title": "Establishing operations"}, {"id": "3c58a7e7-3d52-4f06-8d1c-038a8570a470", "type": "concept", "title": "Deprivation and satiation"}], "description": "Motivation determines what consequences matter, how much effort learners invest, and which behaviors compete for expression."}, {"id": "dc2dd0e8-be96-4022-a444-eae426e9293f", "type": "subtopic", "title": "Emotion and Affective Learning", "children": [{"id": "aa8b76c3-2cab-4a32-a950-878a9ebbd258", "type": "concept", "title": "Fear learning"}, {"id": "1d8461bd-e1c6-4b94-815a-4a97fb3ed62d", "type": "concept", "title": "Appetitive learning"}, {"id": "1c475f66-5f95-44ce-8304-ceebb991bcb3", "type": "concept", "title": "Emotional regulation"}, {"id": "f290abe4-d224-4ff3-b6df-9e1743987d59", "type": "concept", "title": "Affective prediction"}], "description": "Emotion influences attention, memory, avoidance, approach, and the meaning attached to events."}, {"id": "e436609b-60d3-4b33-9338-8e171463d0df", "type": "subtopic", "title": "Stress, Trauma, and Control", "children": [{"id": "685a5cc1-bb9d-44f0-99ab-63ba4ea13d43", "type": "concept", "title": "Acute vs chronic stress"}, {"id": "fc209099-5d1b-439e-9630-e30955e8a9e9", "type": "concept", "title": "Controllability"}, {"id": "901c13b8-0a8d-47db-b785-1421cb76975c", "type": "concept", "title": "Trauma cues"}, {"id": "324876e3-117e-4a3b-ae4f-c35719f394b3", "type": "concept", "title": "Exposure and safety learning"}], "description": "Stress changes learning by altering attention, threat detection, controllability, and memory consolidation."}]}, {"id": "6472dfe0-f715-4964-910f-781bbac780f7", "type": "topic", "title": "Skill Learning, Habits, Automaticity, and Self-Regulation", "description": "Explain how repeated behavior becomes fluent, automatic, habit-like, and sometimes hard to change.", "children": [{"id": "2ab71473-82df-4b61-97af-fb080a1dd11f", "type": "subtopic", "title": "Skill Acquisition", "children": [{"id": "620e4e2c-5201-4514-a845-f2a25d97fd57", "type": "concept", "title": "Practice schedules"}, {"id": "23268401-e9dc-4839-8939-6154cff8ac41", "type": "concept", "title": "Feedback timing"}, {"id": "11060090-df7c-4e69-bc02-ea65625595bf", "type": "concept", "title": "Fluency"}, {"id": "05a62d43-9115-45e6-a0ee-34dba47a0503", "type": "concept", "title": "Transfer of training"}], "description": "Skills develop through feedback, repetition, error correction, and increasingly efficient control."}, {"id": "8f5dcce1-7cba-43a6-a1f5-64a10b101c87", "type": "subtopic", "title": "Habit Formation", "children": [{"id": "dc2cf6e9-793d-447c-8450-ac78360107db", "type": "concept", "title": "Cue-routine-reward loops"}, {"id": "6f5d0e3e-a817-4450-a3b1-5ee8322651d0", "type": "concept", "title": "Automaticity"}, {"id": "921b2546-bf66-4998-869d-8d25df46a851", "type": "concept", "title": "Habit strength"}, {"id": "67802f04-11de-415b-bc0a-cba380db2319", "type": "concept", "title": "Competing routines"}], "description": "Habits are context-triggered action patterns that can be adaptive, stubborn, or harmful depending on consequences and goals."}, {"id": "6e162abd-6101-4698-acd7-db793daf596b", "type": "subtopic", "title": "Self-Regulation and Behavior Change", "children": [{"id": "9e8f0327-5d2a-490b-b4c7-f7c8e89b4ad6", "type": "concept", "title": "Self-monitoring"}, {"id": "04edfa6b-18e8-465f-8205-e2aac1afed97", "type": "concept", "title": "Implementation intentions"}, {"id": "85f52492-9c77-4bec-8c39-4409907483d2", "type": "concept", "title": "Commitment devices"}, {"id": "0286a94e-303f-4b69-bbcd-9bb5666ddf8d", "type": "concept", "title": "Relapse prevention"}], "description": "Self-regulation applies learning principles to goals, monitoring, prompts, reinforcement, and environmental design."}]}, {"id": "0f61be80-a751-47d0-99ea-d961e09727ab", "type": "topic", "title": "Behavior Modification and Intervention Design", "description": "Translate learning principles into assessment-driven behavior-change plans for individuals and systems.", "children": [{"id": "5451ce76-b6c3-4158-b65a-e0a08d4e3721", "type": "subtopic", "title": "Functional Behavior Assessment", "children": [{"id": "d616d3b8-0e97-41ef-8834-fce8cd2f1988", "type": "concept", "title": "Antecedents"}, {"id": "4db7d44a-2008-4ef2-9f61-829839d25fb4", "type": "concept", "title": "Behavior definitions"}, {"id": "ceecbf53-81b6-4d2b-815a-76e2434f77b0", "type": "concept", "title": "Consequences"}, {"id": "ab972d88-ec39-4be4-b0da-2c75f46114b5", "type": "concept", "title": "Direct observation and interviews"}], "description": "Intervention begins by identifying the function of behavior instead of assuming its meaning from appearance alone."}, {"id": "2285c4d0-519f-4f91-8005-87758372e5fc", "type": "subtopic", "title": "Intervention Strategies", "children": [{"id": "dfc74b9b-0b68-43b7-b36b-9fd69bf70858", "type": "concept", "title": "Antecedent interventions"}, {"id": "5a6ea9ba-2b70-4907-9e36-87ff45bd5937", "type": "concept", "title": "Token economies"}, {"id": "7e1e9eaa-aba3-4dc1-8d5a-30266952392b", "type": "concept", "title": "Contingency contracts"}, {"id": "8bee9eb9-78ea-4fca-b60e-789c301eb9e9", "type": "concept", "title": "Differential reinforcement"}], "description": "Behavior modification combines antecedent design, reinforcement, skill teaching, and consequence planning."}, {"id": "4364200b-3fc7-4318-abff-bb91eebc2539", "type": "subtopic", "title": "Measurement and Evaluation", "children": [{"id": "8c6bd47f-159a-4ce8-afc0-133a0d55885f", "type": "concept", "title": "Baseline"}, {"id": "e3ca163e-0563-46c5-80a3-c35112ef8fa2", "type": "concept", "title": "Frequency, duration, latency"}, {"id": "49101c76-5091-41be-a4b1-5de1bdb86bef", "type": "concept", "title": "Graphing behavior"}, {"id": "7102552c-df6c-406f-980e-bd378c4ef086", "type": "concept", "title": "Treatment integrity and social validity"}], "description": "A world-class intervention is measured continuously and revised based on data rather than good intentions."}]}, {"id": "dd45d38d-2b81-4502-a730-47a12868791a", "type": "topic", "title": "Applied Behavior Analysis, Ethics, and Evidence-Based Practice", "description": "Connect behavior analysis to professional practice, measurement, ethics, cultural responsiveness, and client dignity.", "children": [{"id": "ad779bcd-b779-415d-b689-9db49b0702e9", "type": "subtopic", "title": "ABA Dimensions and Practice Logic", "children": [{"id": "6928c0db-eaaa-4918-b56b-a5f02f5f45bb", "type": "concept", "title": "Applied, behavioral, analytic"}, {"id": "47e63204-e84b-42fa-b3fb-634df8436045", "type": "concept", "title": "Technological procedures"}, {"id": "6e06a1be-51ee-4fb3-9c12-f315dc3cc999", "type": "concept", "title": "Conceptually systematic design"}, {"id": "52e1951f-50f7-43b0-9e83-580b9d74abee", "type": "concept", "title": "Generality"}], "description": "Applied behavior analysis is defined by observable behavior, environmental relations, analytic evidence, and socially meaningful outcomes."}, {"id": "2d284ca9-d18d-4035-a135-f2d08dfe32b9", "type": "subtopic", "title": "Ethics, Dignity, and Cultural Responsiveness", "children": [{"id": "3cb52017-72bd-4f8e-9502-734f8e5008db", "type": "concept", "title": "Informed consent"}, {"id": "a30b685a-c2eb-4dee-9ec7-8a17ebd03280", "type": "concept", "title": "Least restrictive alternatives"}, {"id": "80662385-8459-4db5-a560-d0dbae80b27e", "type": "concept", "title": "Client assent and preference"}, {"id": "b4c707fd-92dc-4ddd-b39a-04324258cd30", "type": "concept", "title": "Culturally responsive goals"}], "description": "Ethical practice protects autonomy, consent, dignity, cultural context, and the learner's own goals."}, {"id": "1363d812-5190-4478-85e0-092c1b812138", "type": "subtopic", "title": "Evidence-Based Practice", "children": [{"id": "70e4e975-b282-4034-bc00-0bff58836da4", "type": "concept", "title": "Practice guidelines"}, {"id": "8ac52482-4b1d-47ba-bc59-14eb8c6aaaad", "type": "concept", "title": "Systematic reviews"}, {"id": "73da12f2-ead9-4aa5-a779-0543976e487e", "type": "concept", "title": "Single-case evidence"}, {"id": "ff9668b8-d661-4fa3-b074-5b1f748bef17", "type": "concept", "title": "Generalization and maintenance evidence"}], "description": "Evidence-based behavior work integrates research evidence, practitioner expertise, client values, and ongoing outcome data."}]}, {"id": "de223b7e-b331-4992-9e98-892e16ff5d80", "type": "topic", "title": "Learning in Education, Health, Organizations, and Technology", "description": "Apply learning science to instruction, health behavior, workplace systems, digital products, and behavior-change technologies.", "children": [{"id": "a81c3cbe-4d68-4bce-b6d3-a40fbe58885d", "type": "subtopic", "title": "Education and Instructional Design", "children": [{"id": "7db8531d-5066-4545-8aa8-8ec3666ab8c6", "type": "concept", "title": "Retrieval practice"}, {"id": "0a4f7c16-e900-4d17-b30c-315f4aadadb9", "type": "concept", "title": "Spaced practice"}, {"id": "93a2d286-4de9-4e0e-a7b1-982306d3a295", "type": "concept", "title": "Immediate feedback"}, {"id": "dbc4fd19-e39c-4c16-85bf-96a4ac482653", "type": "concept", "title": "Mastery learning"}], "description": "Learning principles help instructors build clear feedback, active practice, mastery, and durable transfer."}, {"id": "8d994385-e5d2-4f87-881d-5ed8898e1406", "type": "subtopic", "title": "Health and Clinical Behavior Change", "children": [{"id": "d52bcc78-3655-420c-965b-d15a895bbe67", "type": "concept", "title": "Adherence"}, {"id": "dcf0a94b-f807-4f57-b40a-65fbb74bed82", "type": "concept", "title": "Substance use cues"}, {"id": "af3e5e6c-f99f-469f-ac7d-404aad7f36c6", "type": "concept", "title": "Exercise and diet behavior"}, {"id": "ac72766a-903c-4ff4-bd04-1a35a2ae693e", "type": "concept", "title": "Exposure-based treatments"}], "description": "Health interventions use reinforcement, cues, habits, self-monitoring, and relapse planning to support real behavior change."}, {"id": "0b3a659b-eb81-440c-8acb-a36f5f1dc6d2", "type": "subtopic", "title": "Organizations and Digital Systems", "children": [{"id": "64f5dfd1-9fff-4c98-a4a7-ea9f2489f4fe", "type": "concept", "title": "Performance feedback"}, {"id": "fb6e02c9-8786-4af1-8afb-1317195f8ac0", "type": "concept", "title": "Safety behavior"}, {"id": "2c1d6c05-3a00-4c96-a389-9ad09582754d", "type": "concept", "title": "Gamification"}, {"id": "ba1f6b22-736f-47fd-878c-74d07d454266", "type": "concept", "title": "Nudges and dark patterns"}], "description": "Behavioral systems in workplaces and technologies can support or exploit learning, so design must be effective and ethical."}]}, {"id": "5110deeb-6e17-45b7-a98c-a7dab22f1e92", "type": "topic", "title": "Contemporary Debates, Computational Models, and Capstone Behavior-Change Project", "description": "Synthesize learning theory through modern debates, quantitative models, replication, ethics, and a final applied design project.", "children": [{"id": "50df7ec7-6a69-4253-a4a0-a3a95b5728ad", "type": "subtopic", "title": "Computational Learning Models", "children": [{"id": "b2baa0ad-5a8e-483c-8631-1b71a656d400", "type": "concept", "title": "Rescorla-Wagner"}, {"id": "766842e0-4bbb-4ac2-9e8d-01f30742bd02", "type": "concept", "title": "Temporal difference learning"}, {"id": "8e4d4033-4a84-44d2-8de2-6fffab253139", "type": "concept", "title": "Reinforcement learning"}, {"id": "1856e039-15a8-47c1-b8e6-bd48b0ff9982", "type": "concept", "title": "Model-free vs model-based learning"}], "description": "Computational models formalize learning as prediction, value updating, exploration, and action selection."}, {"id": "856f08eb-53fd-40f4-b05c-db21ce30272d", "type": "subtopic", "title": "Debates and Open Science", "children": [{"id": "dbeda539-ad15-4e70-ac37-7d9ddcf85094", "type": "concept", "title": "Replication"}, {"id": "36db0dc8-e388-43d8-8e5c-c845e8f0edb1", "type": "concept", "title": "Preregistration"}, {"id": "aa0d3a2e-d373-43a9-a27d-a146b6a98b81", "type": "concept", "title": "Translational limits"}, {"id": "ba43ea51-c2b3-4ea5-8a5c-2566f7110bff", "type": "concept", "title": "Laboratory vs naturalistic behavior"}], "description": "Current learning science wrestles with reproducibility, ecological validity, animal models, ethics, and generalization to human life."}, {"id": "90c27dbd-8b75-4a7f-82e2-3d18cbfbd6a0", "type": "subtopic", "title": "Capstone Behavior-Change Project", "children": [{"id": "95ff564e-9871-4be3-9d72-1666cfebb8bd", "type": "concept", "title": "Problem definition"}, {"id": "105840fb-6330-4450-b95d-150123754750", "type": "concept", "title": "Functional assessment"}, {"id": "e1b10e73-184e-43ed-b0e3-c5bae765b7b4", "type": "concept", "title": "Intervention plan"}, {"id": "ba55f54f-1a25-4fe4-8b5e-b1f61b78a6b6", "type": "concept", "title": "Evaluation and reflection"}], "description": "The capstone asks students to diagnose a behavior problem and design a measurable, ethical, evidence-based intervention."}]}], "dbBacked": true}$lbehjson$::jsonb,
