insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1e4329c0-8353-4eb2-8be2-1d6f64c74d07', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Foundations of Learning Science and Behavior Analysis', 'Define learning as behavior change through experience, connect major traditions, and establish the course''s experimental and applied logic.', 0),
  ('62d88ff9-9aa5-4aae-82e2-e464af6081f9', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '1e4329c0-8353-4eb2-8be2-1d6f64c74d07', 'subtopic'::public.curated_course_node_type, 'What Counts as Learning', 'This subtopic establishes learning as a measurable change in behavior or behavioral potential caused by experience, not simply maturation or temporary state change.', 0),
  ('85e9b9f4-df4c-4238-83f4-dcc9c22f8e71', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '62d88ff9-9aa5-4aae-82e2-e464af6081f9', 'concept'::public.curated_course_node_type, 'Behavior vs behavioral potential', null, 0),
  ('d7eef5ac-4b22-4df9-9349-4fae52e26e8c', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '62d88ff9-9aa5-4aae-82e2-e464af6081f9', 'concept'::public.curated_course_node_type, 'Experience and practice', null, 1),
  ('414f5954-7a5d-48ee-bab6-73b4c9fb3a30', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '62d88ff9-9aa5-4aae-82e2-e464af6081f9', 'concept'::public.curated_course_node_type, 'Performance vs learning', null, 2),
  ('83f86996-5e2d-4947-afd6-0a1484851e63', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '62d88ff9-9aa5-4aae-82e2-e464af6081f9', 'concept'::public.curated_course_node_type, 'Maturation, fatigue, and drug effects', null, 3),
  ('753a4b9b-93ba-4b6c-8405-8edb92d2e4fd', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '1e4329c0-8353-4eb2-8be2-1d6f64c74d07', 'subtopic'::public.curated_course_node_type, 'History of Learning Theory', 'A strong foundation requires seeing how associationism, behaviorism, cognitive psychology, and behavior analysis each framed the study of change.', 1),
  ('44f6c607-d539-4414-9454-c3622a044536', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '753a4b9b-93ba-4b6c-8405-8edb92d2e4fd', 'concept'::public.curated_course_node_type, 'Associationism', null, 0),
  ('232c15b0-3c06-4c3f-8b2b-b36fd921a089', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '753a4b9b-93ba-4b6c-8405-8edb92d2e4fd', 'concept'::public.curated_course_node_type, 'Pavlov and Thorndike', null, 1),
  ('8e9e26b6-cab1-4c94-9bc8-b0a342141f0c', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '753a4b9b-93ba-4b6c-8405-8edb92d2e4fd', 'concept'::public.curated_course_node_type, 'Watson and Skinner', null, 2),
  ('39e46ba9-5777-4643-a027-bf4d208cb412', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '753a4b9b-93ba-4b6c-8405-8edb92d2e4fd', 'concept'::public.curated_course_node_type, 'Tolman, Bandura, and cognitive turns', null, 3),
  ('d5d10e46-0b75-41c9-89dd-e164c379915e', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '1e4329c0-8353-4eb2-8be2-1d6f64c74d07', 'subtopic'::public.curated_course_node_type, 'Scientific Method in Learning Research', 'Learning and behavior are studied through careful operational definitions, experimental control, replication, and precise measurement.', 2),
  ('ae53a89b-6db6-4b90-a39c-c606b73823eb', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'd5d10e46-0b75-41c9-89dd-e164c379915e', 'concept'::public.curated_course_node_type, 'Independent and dependent variables', null, 0),
  ('9c73b8b4-57db-4615-8404-711c08b9842d', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'd5d10e46-0b75-41c9-89dd-e164c379915e', 'concept'::public.curated_course_node_type, 'Within-subject designs', null, 1),
  ('e6900b77-5916-4e68-91b4-86277b46b550', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'd5d10e46-0b75-41c9-89dd-e164c379915e', 'concept'::public.curated_course_node_type, 'Single-case logic', null, 2),
  ('05d7b54f-3952-411b-a484-72c23263769a', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'd5d10e46-0b75-41c9-89dd-e164c379915e', 'concept'::public.curated_course_node_type, 'Reliability, validity, and replication', null, 3),
  ('bdada2f9-e0b7-4e0b-bd40-8a3411330973', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Classical Conditioning and Associative Learning', 'Explain how organisms learn predictive relations among stimuli and why these associations matter for emotion, preparation, and adaptation.', 1),
  ('9c9d9770-3aae-44ed-9628-9c96af6a26b4', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'bdada2f9-e0b7-4e0b-bd40-8a3411330973', 'subtopic'::public.curated_course_node_type, 'Basic Classical Conditioning', 'Classical conditioning explains how neutral cues become meaningful predictors of biologically important events.', 0),
  ('5c607b18-eef2-45a8-9368-7e54cd36c653', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9c9d9770-3aae-44ed-9628-9c96af6a26b4', 'concept'::public.curated_course_node_type, 'Unconditioned stimulus and response', null, 0),
  ('a435aeed-79a8-4a05-8b7a-3a445bca51ab', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9c9d9770-3aae-44ed-9628-9c96af6a26b4', 'concept'::public.curated_course_node_type, 'Conditioned stimulus and response', null, 1),
  ('5f9476e3-8246-4c82-8be5-122b4e80db70', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9c9d9770-3aae-44ed-9628-9c96af6a26b4', 'concept'::public.curated_course_node_type, 'Acquisition', null, 2),
  ('a83d6bf1-0ec3-415f-bb20-6f04ccda2d3d', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9c9d9770-3aae-44ed-9628-9c96af6a26b4', 'concept'::public.curated_course_node_type, 'Timing and contiguity', null, 3),
  ('0b39ffce-b41d-4b34-834e-b9eb979525e0', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'bdada2f9-e0b7-4e0b-bd40-8a3411330973', 'subtopic'::public.curated_course_node_type, 'Associative Mechanisms', 'Modern accounts ask what exactly is learned: a simple link, a prediction, an expectation, or a representation of event relations.', 1),
  ('c65b82a9-4d8a-45b2-b222-cf7eba7ed9c7', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '0b39ffce-b41d-4b34-834e-b9eb979525e0', 'concept'::public.curated_course_node_type, 'Contingency vs contiguity', null, 0),
  ('434cc379-1b83-498c-afd5-19cea669901b', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '0b39ffce-b41d-4b34-834e-b9eb979525e0', 'concept'::public.curated_course_node_type, 'Blocking', null, 1),
  ('b8c091ff-e7e6-4169-aebc-f4dfb8712581', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '0b39ffce-b41d-4b34-834e-b9eb979525e0', 'concept'::public.curated_course_node_type, 'Prediction error', null, 2),
  ('692624f6-aafc-43a4-9b12-6dd80e8ed08e', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '0b39ffce-b41d-4b34-834e-b9eb979525e0', 'concept'::public.curated_course_node_type, 'Rescorla-Wagner model', null, 3),
  ('24c34d6e-a9a5-45c0-a3f7-25611570b4bf', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'bdada2f9-e0b7-4e0b-bd40-8a3411330973', 'subtopic'::public.curated_course_node_type, 'Emotional and Physiological Conditioning', 'Conditioning is central to fear, taste aversion, immune responses, addiction cues, and preparedness for action.', 2),
  ('6007426e-87d7-478a-9bf7-7f905c41dd37', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '24c34d6e-a9a5-45c0-a3f7-25611570b4bf', 'concept'::public.curated_course_node_type, 'Fear conditioning', null, 0),
  ('328184e8-1499-4adb-bf9e-e7889631627c', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '24c34d6e-a9a5-45c0-a3f7-25611570b4bf', 'concept'::public.curated_course_node_type, 'Conditioned emotional response', null, 1),
  ('093292cf-9641-497d-8b68-157509c25157', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '24c34d6e-a9a5-45c0-a3f7-25611570b4bf', 'concept'::public.curated_course_node_type, 'Taste aversion', null, 2),
  ('8e1bee6a-fb88-41a4-b46c-971b03f56816', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '24c34d6e-a9a5-45c0-a3f7-25611570b4bf', 'concept'::public.curated_course_node_type, 'Conditioned tolerance and cue reactivity', null, 3),
  ('b41efea8-2411-4027-a9c9-8253c44f6d70', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Operant Conditioning and Consequences', 'Analyze how consequences shape voluntary behavior through reinforcement, punishment, response cost, shaping, and feedback.', 2),
  ('e93b0755-46d7-4293-a8f7-80f4d6d601d2', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'b41efea8-2411-4027-a9c9-8253c44f6d70', 'subtopic'::public.curated_course_node_type, 'Thorndike, Skinner, and Operant Logic', 'Operant conditioning studies how behavior is selected by its consequences in a particular environment.', 0),
  ('c423192c-fad3-4287-ab05-79e392cdf6db', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e93b0755-46d7-4293-a8f7-80f4d6d601d2', 'concept'::public.curated_course_node_type, 'Law of effect', null, 0),
  ('033e4c58-5676-46d0-958e-1656860a6d72', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e93b0755-46d7-4293-a8f7-80f4d6d601d2', 'concept'::public.curated_course_node_type, 'Operant chamber', null, 1),
  ('32c54a97-6e6f-443f-a5a8-b693db886570', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e93b0755-46d7-4293-a8f7-80f4d6d601d2', 'concept'::public.curated_course_node_type, 'Response classes', null, 2),
  ('5fcbadb6-707d-463a-a6e5-9da130f2ad1b', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e93b0755-46d7-4293-a8f7-80f4d6d601d2', 'concept'::public.curated_course_node_type, 'Three-term contingency', null, 3),
  ('6d240431-bfd6-487b-b323-73d95626196d', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'b41efea8-2411-4027-a9c9-8253c44f6d70', 'subtopic'::public.curated_course_node_type, 'Reinforcement and Response Strength', 'Reinforcement is the process by which consequences increase future behavior, but its effects depend on timing, value, and context.', 1),
  ('f1dcffc8-a1a5-4ab6-bd8c-8e90a40ac408', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '6d240431-bfd6-487b-b323-73d95626196d', 'concept'::public.curated_course_node_type, 'Positive reinforcement', null, 0);
