  ('971fdc45-1261-44b3-838b-e1268f26e26c', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '6d240431-bfd6-487b-b323-73d95626196d', 'concept'::public.curated_course_node_type, 'Negative reinforcement', null, 1),
