  ('45eb401c-2f76-49cd-9e81-76cdad363826', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '6d240431-bfd6-487b-b323-73d95626196d', 'concept'::public.curated_course_node_type, 'Immediacy and magnitude', null, 3),
  ('9055872d-18c8-4c9b-9c9c-92459775de62', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'b41efea8-2411-4027-a9c9-8253c44f6d70', 'subtopic'::public.curated_course_node_type, 'Shaping and Chaining', 'Complex behavior is often built gradually by reinforcing approximations and linking smaller responses into useful sequences.', 2),
  ('23803dbc-4ac3-4def-b049-f1ea849a7743', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9055872d-18c8-4c9b-9c9c-92459775de62', 'concept'::public.curated_course_node_type, 'Successive approximations', null, 0),
  ('356d0010-4157-4178-a0cc-abb9e53cd8f4', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9055872d-18c8-4c9b-9c9c-92459775de62', 'concept'::public.curated_course_node_type, 'Prompting and fading', null, 1),
  ('2ad3f3ae-0788-4390-9768-e6f77d8bd999', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9055872d-18c8-4c9b-9c9c-92459775de62', 'concept'::public.curated_course_node_type, 'Task analysis', null, 2),
  ('0121418d-5ee0-44ce-9724-b08566761f24', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '9055872d-18c8-4c9b-9c9c-92459775de62', 'concept'::public.curated_course_node_type, 'Forward and backward chaining', null, 3),
  ('8896a53f-d8b0-40a3-b30a-8d38383d4733', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Reinforcement, Punishment, Avoidance, and Behavioral Momentum', 'Compare consequence-based processes and learn how they strengthen, suppress, redirect, or maintain behavior over time.', 3),
  ('6cc141d0-c48f-4838-8ba9-04a450aaf0b7', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '8896a53f-d8b0-40a3-b30a-8d38383d4733', 'subtopic'::public.curated_course_node_type, 'Punishment and Response Suppression', 'Punishment can reduce behavior, but it raises practical, ethical, and side-effect questions that must be handled carefully.', 0),
  ('a8caea26-8cc1-4284-98f1-ef3a7585e71d', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '6cc141d0-c48f-4838-8ba9-04a450aaf0b7', 'concept'::public.curated_course_node_type, 'Positive punishment', null, 0),
  ('38a11b5c-1e40-4ff5-9a27-f7e45a75fcf2', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '6cc141d0-c48f-4838-8ba9-04a450aaf0b7', 'concept'::public.curated_course_node_type, 'Negative punishment', null, 1),
  ('db46898e-adde-41d7-9c44-ec7c48b6cd12', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '6cc141d0-c48f-4838-8ba9-04a450aaf0b7', 'concept'::public.curated_course_node_type, 'Response cost', null, 2),
  ('7e0f876e-3a5c-4df8-be2a-ddda686a9c51', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '6cc141d0-c48f-4838-8ba9-04a450aaf0b7', 'concept'::public.curated_course_node_type, 'Side effects and ethical limits', null, 3),
  ('1aec6616-23c0-48eb-8fe7-d4f8ba5c80ca', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '8896a53f-d8b0-40a3-b30a-8d38383d4733', 'subtopic'::public.curated_course_node_type, 'Avoidance and Escape Learning', 'Avoidance learning shows how behavior can be maintained by preventing or ending aversive events, even when danger is absent.', 1),
  ('9be2355b-55cc-4833-bed2-95b8e7c51606', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '1aec6616-23c0-48eb-8fe7-d4f8ba5c80ca', 'concept'::public.curated_course_node_type, 'Escape conditioning', null, 0),
  ('967617bd-acd4-4a8a-b9e1-3b86ea1ee9d4', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '1aec6616-23c0-48eb-8fe7-d4f8ba5c80ca', 'concept'::public.curated_course_node_type, 'Avoidance schedules', null, 1),
  ('41409dfb-db86-4c62-b7c9-496d742503f1', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '1aec6616-23c0-48eb-8fe7-d4f8ba5c80ca', 'concept'::public.curated_course_node_type, 'Two-factor theory', null, 2),
  ('93f0965c-a499-465d-9ba7-cd7895780a4f', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '1aec6616-23c0-48eb-8fe7-d4f8ba5c80ca', 'concept'::public.curated_course_node_type, 'Learned helplessness and controllability', null, 3),
  ('cf2aaa30-1f30-4937-af26-8aa3ecd9ff54', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '8896a53f-d8b0-40a3-b30a-8d38383d4733', 'subtopic'::public.curated_course_node_type, 'Behavioral Momentum', 'Behavioral momentum explains why some behavior persists despite disruption and how reinforcement history affects resistance to change.', 2),
  ('d3494ce4-675a-4819-9dda-4408bf573652', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'cf2aaa30-1f30-4937-af26-8aa3ecd9ff54', 'concept'::public.curated_course_node_type, 'Baseline reinforcement rate', null, 0),
  ('300eb6ec-391d-464a-a393-83a877df56fa', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'cf2aaa30-1f30-4937-af26-8aa3ecd9ff54', 'concept'::public.curated_course_node_type, 'Persistence', null, 1),
  ('a7e515cd-3c5b-49dd-943f-d69bc53c4e4b', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'cf2aaa30-1f30-4937-af26-8aa3ecd9ff54', 'concept'::public.curated_course_node_type, 'Disruptors', null, 2),
  ('947a9ecc-892f-4169-8462-47f7d9b6eb88', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'cf2aaa30-1f30-4937-af26-8aa3ecd9ff54', 'concept'::public.curated_course_node_type, 'High-probability request sequences', null, 3),
  ('fc50b496-97ee-4e6c-9b7a-bce0ec83665a', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Schedules of Reinforcement, Choice, and Matching', 'Study how timing and probability of consequences create distinctive patterns of behavior and decision making.', 4),
  ('ec0debe8-a23e-4d61-9e33-815f78225184', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'fc50b496-97ee-4e6c-9b7a-bce0ec83665a', 'subtopic'::public.curated_course_node_type, 'Ratio and Interval Schedules', 'Schedules of reinforcement reveal how the pattern of consequences controls response rate, pauses, and persistence.', 0),
  ('1a8dae19-b637-4332-aa17-5358305320e0', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'ec0debe8-a23e-4d61-9e33-815f78225184', 'concept'::public.curated_course_node_type, 'Fixed ratio', null, 0),
