  ('aad57ffe-f9ba-4559-8a00-d9422c884959', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'ec0debe8-a23e-4d61-9e33-815f78225184', 'concept'::public.curated_course_node_type, 'Fixed interval', null, 2),
