  ('000cfb0a-8cdf-4dfd-afc7-3aa9bea716eb', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'fc50b496-97ee-4e6c-9b7a-bce0ec83665a', 'subtopic'::public.curated_course_node_type, 'Differential Reinforcement', 'Differential reinforcement teaches learners which forms, rates, or timing of behavior are useful.', 1),
  ('0cbcd00f-89f4-4817-8346-2d2f1d0ba7fc', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '000cfb0a-8cdf-4dfd-afc7-3aa9bea716eb', 'concept'::public.curated_course_node_type, 'DRA', null, 0),
