  ('15400e93-60f6-4ddc-b655-ec2733da6b6b', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '000cfb0a-8cdf-4dfd-afc7-3aa9bea716eb', 'concept'::public.curated_course_node_type, 'DRO', null, 2),
  ('f3c7de2d-5934-4a60-8a9e-6f55169b5d21', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '000cfb0a-8cdf-4dfd-afc7-3aa9bea716eb', 'concept'::public.curated_course_node_type, 'DRL and DRH', null, 3),
  ('305a06ea-2e03-4b48-b690-49777537e488', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'fc50b496-97ee-4e6c-9b7a-bce0ec83665a', 'subtopic'::public.curated_course_node_type, 'Choice and Matching', 'Choice research links learning to allocation of behavior across options, rewards, delays, and effort.', 2),
  ('42d8606e-5fed-4170-bb41-921e344e7385', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '305a06ea-2e03-4b48-b690-49777537e488', 'concept'::public.curated_course_node_type, 'Matching law', null, 0),
