insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('d74da1a5-6046-4fda-bd62-8c9601a9133f', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Extinction, Spontaneous Recovery, Renewal, and Relapse', 'Understand why learned behavior returns after change efforts and how durable behavior change is designed.', 5),
  ('ee9a01e9-9eaf-423a-af96-cc593847ad42', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'd74da1a5-6046-4fda-bd62-8c9601a9133f', 'subtopic'::public.curated_course_node_type, 'Extinction Processes', 'Extinction is not erasure; it is new learning that behavior or cues no longer produce the expected outcome.', 0),
  ('051562a9-013d-469d-a199-21e366f5cad7', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'ee9a01e9-9eaf-423a-af96-cc593847ad42', 'concept'::public.curated_course_node_type, 'Extinction bursts', null, 0),
  ('befc3c3c-70c0-4e00-aaa3-fa72e4ef18fd', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'ee9a01e9-9eaf-423a-af96-cc593847ad42', 'concept'::public.curated_course_node_type, 'Emotional responding', null, 1),
  ('ca823239-4948-4749-afb4-86edcc7831ff', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'ee9a01e9-9eaf-423a-af96-cc593847ad42', 'concept'::public.curated_course_node_type, 'Extinction as inhibitory learning', null, 2),
  ('64bc8397-f1be-4bdc-8a11-f59932f3cce4', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'ee9a01e9-9eaf-423a-af96-cc593847ad42', 'concept'::public.curated_course_node_type, 'Context dependence', null, 3),
  ('80fde040-da2a-4e08-9f6b-bef03d42056a', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'd74da1a5-6046-4fda-bd62-8c9601a9133f', 'subtopic'::public.curated_course_node_type, 'Recovery and Return of Behavior', 'Behavior often comes back, so students need to understand the major relapse phenomena before designing interventions.', 1),
  ('972569e9-2bce-442d-a73d-d8188d4da974', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '80fde040-da2a-4e08-9f6b-bef03d42056a', 'concept'::public.curated_course_node_type, 'Spontaneous recovery', null, 0),
  ('72239095-a812-4990-be83-f272b9c8e4f2', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '80fde040-da2a-4e08-9f6b-bef03d42056a', 'concept'::public.curated_course_node_type, 'Renewal', null, 1),
  ('b6177246-2c1f-47ad-aa13-3080df6cb4e4', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '80fde040-da2a-4e08-9f6b-bef03d42056a', 'concept'::public.curated_course_node_type, 'Reinstatement', null, 2),
  ('1466d999-df96-495d-80f9-7fe1025fff26', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '80fde040-da2a-4e08-9f6b-bef03d42056a', 'concept'::public.curated_course_node_type, 'Resurgence', null, 3),
  ('42c41960-432f-4ebc-babb-8436808201d8', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'd74da1a5-6046-4fda-bd62-8c9601a9133f', 'subtopic'::public.curated_course_node_type, 'Durable Behavior Change', 'Durable change requires planning for generalization, maintenance, competing reinforcement, and real-world relapse risks.', 2),
  ('de43f751-353f-4a1e-907f-02612067ee88', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '42c41960-432f-4ebc-babb-8436808201d8', 'concept'::public.curated_course_node_type, 'Thinning reinforcement', null, 0),
  ('5dc642db-8d12-4f5d-8d52-8af74ea94f4b', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '42c41960-432f-4ebc-babb-8436808201d8', 'concept'::public.curated_course_node_type, 'Multiple contexts', null, 1),
  ('f532254a-7741-4ce3-ad8f-28a54cb36a56', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '42c41960-432f-4ebc-babb-8436808201d8', 'concept'::public.curated_course_node_type, 'Booster sessions', null, 2),
  ('ae973330-fdac-4564-8b63-37e41e901d92', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '42c41960-432f-4ebc-babb-8436808201d8', 'concept'::public.curated_course_node_type, 'Replacement behavior maintenance', null, 3),
  ('52e7e5d6-0fe5-4ed6-ba92-b908ab1e9c69', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Stimulus Control, Discrimination, Generalization, and Context', 'Learn how cues, settings, categories, and contexts guide behavior and transfer learning across situations.', 6),
  ('39b156b4-3fff-4219-a875-279cee80b2eb', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '52e7e5d6-0fe5-4ed6-ba92-b908ab1e9c69', 'subtopic'::public.curated_course_node_type, 'Stimulus Control', 'Stimulus control explains how cues signal when behavior is likely to work, making behavior flexible and situation-sensitive.', 0),
  ('21bbd5dc-4ba1-4fc6-a7d5-29321d7f881b', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '39b156b4-3fff-4219-a875-279cee80b2eb', 'concept'::public.curated_course_node_type, 'Discriminative stimulus', null, 0),
  ('22db3ef8-6163-4842-9026-537a0e1c1ed4', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '39b156b4-3fff-4219-a875-279cee80b2eb', 'concept'::public.curated_course_node_type, 'S-delta', null, 1),
  ('02ab7eb5-5080-4b48-8334-a0d3fe9affd1', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '39b156b4-3fff-4219-a875-279cee80b2eb', 'concept'::public.curated_course_node_type, 'Cue salience', null, 2),
  ('4bfed1f9-f072-4389-942e-968c862b449e', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '39b156b4-3fff-4219-a875-279cee80b2eb', 'concept'::public.curated_course_node_type, 'Occasion setting', null, 3),
  ('e0c65cf1-eca7-442b-bc23-51dff651a71c', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', '52e7e5d6-0fe5-4ed6-ba92-b908ab1e9c69', 'subtopic'::public.curated_course_node_type, 'Discrimination and Generalization', 'Learners must know when to treat situations as different and when to transfer learning across similar cases.', 1),
  ('94fe5459-4fdc-4df4-a9be-feddcec31b96', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e0c65cf1-eca7-442b-bc23-51dff651a71c', 'concept'::public.curated_course_node_type, 'Generalization gradients', null, 0),
  ('0fb363a7-b6b6-45c4-ab49-4e80bcbc228a', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e0c65cf1-eca7-442b-bc23-51dff651a71c', 'concept'::public.curated_course_node_type, 'Discrimination training', null, 1),
  ('a620c150-877c-4049-ae70-20779e0b0963', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e0c65cf1-eca7-442b-bc23-51dff651a71c', 'concept'::public.curated_course_node_type, 'Peak shift', null, 2),
  ('fd58fc7a-02d3-4ab2-a16b-ec729586768a', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'e0c65cf1-eca7-442b-bc23-51dff651a71c', 'concept'::public.curated_course_node_type, 'Concept learning', null, 3),
