  ('48b2c8f1-76cd-4383-9ea2-12b1a6e2b6c4', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'bee8eb40-3530-451a-a966-c3bd7d0ef64d', 'concept'::public.curated_course_node_type, 'Physical context', null, 0),
  ('8faeccff-93b7-476a-880c-1cff5c3eccb6', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'bee8eb40-3530-451a-a966-c3bd7d0ef64d', 'concept'::public.curated_course_node_type, 'Social context', null, 1),
  ('656391e0-bcbd-41ad-b181-e5171e9cec50', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'bee8eb40-3530-451a-a966-c3bd7d0ef64d', 'concept'::public.curated_course_node_type, 'Internal state', null, 2),
  ('7338d25b-e03a-48d1-bdd7-2ea007fe7006', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'bee8eb40-3530-451a-a966-c3bd7d0ef64d', 'concept'::public.curated_course_node_type, 'Transfer-appropriate learning', null, 3),
  ('a9f98253-77b9-4578-8899-8db750be849c', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Observational Learning, Imitation, and Social Learning', 'Examine how people and animals learn from models, social consequences, instruction, and culture.', 7),
  ('aa3e279c-3e67-4dcb-a9f5-e11206e45ad1', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'a9f98253-77b9-4578-8899-8db750be849c', 'subtopic'::public.curated_course_node_type, 'Bandura and Social Learning', 'People learn by watching others, interpreting outcomes, and forming expectations, not only by direct reinforcement.', 0),
  ('24be3dc7-74e4-4115-bd00-9f3814bd6659', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'aa3e279c-3e67-4dcb-a9f5-e11206e45ad1', 'concept'::public.curated_course_node_type, 'Bobo doll studies', null, 0),
  ('8c631e70-dd6b-4a4b-ae95-00591c0ce77d', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'aa3e279c-3e67-4dcb-a9f5-e11206e45ad1', 'concept'::public.curated_course_node_type, 'Vicarious reinforcement', null, 1),
  ('be18495c-98d2-4cb7-bb3b-ff52c1a226ad', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'aa3e279c-3e67-4dcb-a9f5-e11206e45ad1', 'concept'::public.curated_course_node_type, 'Attention and retention', null, 2),
  ('37c825b6-c1fe-49ee-aae5-370be5011b92', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'aa3e279c-3e67-4dcb-a9f5-e11206e45ad1', 'concept'::public.curated_course_node_type, 'Motivation and reproduction', null, 3),
  ('ae84bab3-9b7e-4de6-b574-4826b7582429', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'a9f98253-77b9-4578-8899-8db750be849c', 'subtopic'::public.curated_course_node_type, 'Imitation and Modeling', 'Imitation is a powerful route to skill acquisition, social behavior, language, and cultural transmission.', 1),
  ('356a6d6f-d6ce-4751-88f8-38a85054138e', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', 'ae84bab3-9b7e-4de6-b574-4826b7582429', 'concept'::public.curated_course_node_type, 'Model characteristics', null, 0);
