  ('ae650428-1837-4e55-b0c7-564f4a0c0eda', 'a7c8d9e0-1f2a-4b77-8c67-7d8e9f0a1b27', null, 'topic'::public.curated_course_node_type, 'Cognitive, Neural, and Evolutionary Perspectives on Learning', 'Integrate behaviorist findings with cognition, neuroscience, memory systems, animal cognition, and biological constraints.', 8),
